Rules.InvariantScript:
UpdateContext({DateNow:Text(Now(),"[$-en-US]dddd mm/dd/yyyy")}); UpdateContext({TimeNow: Text(Now(), "[$-en-US] hh:mm:ss AM/PM")});

// Screen_Home.OnVisible
Refresh(AttendingList);

With(
    {
        me: LookUp(
            AttendingList,
            Lower(Trim(EmailAddress)) = Lower(Trim(User().Email))
        )
    },
    Set(
        gblIsProgramDirector,
        !IsBlank(me) &&
        (
            Lower(Trim(me.AttendingRole)) = "program director" ||
            Lower(Trim(me.AttendingRole)) = "pd" ||
            Lower(Trim(me.AttendingRole)) = "program dir" ||
            Lower(Trim(me.AttendingRole)) = "chair" ||
            Lower(Trim(me.AttendingRole)) = "division chief" ||
            Lower(Trim(me.AttendingRole)) = "admin" ||
            Lower(Trim(me.AttendingRole)) = "administrator"
        )
    )
);

NewForm(frmFeedback);
Navigate(
    screenFeedback,
    ScreenTransition.None,
    {  
        navMode: "new",           
        selRecord: Blank(),
        sourceGallery: Blank()
  
    }
)

